states.9e80a274266e:
{
 "kayit": {
  "no": "ITR-47029"
 },
 "gecmis": [
  "«dosya sonuçlandırıldı» adımını otomatik sistem tamamladı.",
  "«üye işyerine bildirim gönderildi» adımını uzman (Şule Kaya) tamamladı.",
  "«itiraz kaydı açıldı» adımını otomatik sistem tamamladı."
 ],
 "notlar": [
  "Ahmet Şahin, yeni ekran tasarımını beğendiğini belirtti.",
  "İtiraz dosyası ile ilgili tüm yazışmalar Müşteri İlişkileri ortak kutusuna kopyalanır.",
  "Müşteriye gönderilen bilgilendirmeler sade bir dille ve kurum şablonu kullanılarak hazırlanır.",
  "Yönetici her hafta açık itiraz dosyası listesini gözden geçirir ve gerekirse not ekler.",
  "Ters İbraz Birimi personeli için yeni bir bilgilendirme toplantısı planlanıyor.",
  "Görüşme notları sisteme kısa süre içinde girildi."
 ]
}

states.9e5e9433a6c6:
{
 "kayit": {
  "Kayıt no": "INC-25928",
  "Kesinti süresi": "583 dakika",
  "Aciliyet": "düşük"
 },
 "politika": "Etki: kesinti süresi 200 dakika veya altı → düşük; 200 dakika üstü 600 dakika veya altı → orta; 600 dakika üstü → yüksek. Düzey matrisi: etki düşük × aciliyet düşük → «P4 düşük»; etki düşük × aciliyet orta → «P3 orta»; etki düşük × aciliyet yüksek → «P2 yüksek»; etki orta × aciliyet düşük → «P3 orta»; etki orta × aciliyet orta → «P2 yüksek»; etki orta × aciliyet yüksek → «P1 kritik»; etki yüksek × aciliyet düşük → «P2 yüksek»; etki yüksek × aciliyet orta → «P1 kritik»; etki yüksek × aciliyet yüksek → «P1 kritik»."
}

