{
 "bugun": "2026-09-30",
 "vaka": {
  "vaka_no": "UYM-2026-3317",
  "acilis_nedeni": "Senaryo S-44: 30 gün içinde 40'tan fazla farklı kişiden birbirine yakın tutarlarda gelen havale",
  "atanan_analist": "Gülizar Tekinalp",
  "durum": "İnceleme sürüyor"
 },
 "kayit_a_banka_musterisi": {
  "ad_soyad": "Kerem Çalışkan",
  "dogum_tarihi": "14.03.1991",
  "ikamet": "Bornova / İzmir (hesap açılışından beri değişmedi)",
  "telefon": "0532 *** 41 07",
  "meslek_beyani": "Serbest — dijital içerik üreticisi (finans ve borsa yorumları)",
  "hesap_acilis": "2024-11-06, İzmir Kazımdirik şubesi",
  "iban_son_dort_hane": "4417",
  "beyan_edilen_aylik_gelir_tl": "45.000",
  "kyc_notu": "Hesap açılışında müşteri, YouTube ve Telegram'da finans içerikleri ürettiğini, gelirinin reklam ve sponsorluk anlaşmalarından geldiğini beyan etmiş; vergi levhası fotokopisi dosyada. Son KYC güncellemesi 2025-11-20 tarihinde mobil uygulamadan yapılmış, adres ve telefon bilgisi değişmemiş. Müşterinin bankada başka ürünü olarak bir kredi kartı ve bir vadeli mevduat hesabı (bakiyesi 2025 sonunda kapatılmış) bulunuyor."
 },
 "kayit_b_spk_bulteni": {
  "kaynak": "SPK Bülteni 2026/31 (30.07.2026), analistin vaka dosyasına eklediği bölümler",
  "ilk_halka_arz_onaylari": "Doğankaya Gıda Sanayi A.Ş.'nin 120.000.000 TL nominal değerli paylarının halka arzına ilişkin izahname onaylandı. Erenler Lojistik A.Ş.'nin sermaye artırımı yoluyla ihraç edeceği payların halka arzı onaylandı.",
  "borclanma_araclari": "Üç bankanın toplam 18 milyar TL'ye kadar borçlanma aracı ihraç tavanı başvurusu onaylandı; bir finansman şirketinin kira sertifikası ihracı onaylandı.",
  "idari_para_cezalari": "Selvi Enerji Yatırım A.Ş.'ye özel durum açıklamasını zamanında yapmaması nedeniyle 412.660 TL idari para cezası uygulandı.",
  "suc_duyurusu_ve_islem_yasaklari": "Arven Tekstil Sanayi A.Ş. (ARVEN) paylarında 03.02.2025-21.03.2025 döneminde gerçekleştirilen işlemlerin SPKn 107/1 kapsamında piyasa dolandırıcılığı teşkil edebileceği değerlendirildiğinden Kerem Çalışkan, Sedat Ilgın ve Nurten Akbaş hakkında suç duyurusunda bulunulmasına ve bu kişilere SPKn 101/1-b uyarınca 2 yıl süreyle pay piyasalarında işlem yasağı getirilmesine karar verildi. Ayrıca Tunay Demirhisar hakkında, Pelin Kimya A.Ş. paylarında bilgi bazlı piyasa dolandırıcılığı şüphesiyle suç duyurusunda bulunulmasına karar verildi.",
  "erisim_engelleri": "İzinsiz sermaye piyasası faaliyeti yürüttüğü tespit edilen 9 internet sitesi ve izinsiz kripto varlık hizmeti sunan 6 internet sitesi hakkında erişim engeli için yasal işlem başlatıldı.",
  "kurumsal_kararlar": "İki portföy yönetim şirketinin serbest fon kuruluş başvuruları onaylandı. Bir aracı kurumun kaldıraçlı alım satım işlemlerine aracılık yetkisinin, sermaye yeterliliği tablolarındaki eksiklik giderilene kadar yeni müşteri kabul etmeyecek şekilde sınırlandırılmasına karar verildi. Bir bağımsız denetim kuruluşunun yetki belgesi kendi talebi üzerine iptal edildi.",
  "not": "Bülten, işlem yasağı getirilen kişilerin kimlik numarası, doğum tarihi veya adres bilgisini içermiyor."
 },
 "haber_kupuru": "Yerel bir haber sitesi, 05.08.2026: 'SPK'nın son bülteninde suç duyurusunda bulunulan 3 kişi arasında, sosyal medyada borsa yorumlarıyla tanınan ve Bursa'da yaşayan 35 yaşındaki K.Ç.'nin de bulunduğu öğrenildi. K.Ç.'nin Bursa'daki bir aracı kurumda uzun süre müşteri temsilcisi olarak çalıştığı belirtildi.'",
 "telegram_kanal_ornekleri": [
  {
   "tarih": "2026-08-11 21:04",
   "kanal": "Boğa Masası (herkese açık)",
   "metin": "Arkadaşlar VIP kayıtlar açıldı. Aylık 2.500 TL, 3 aylık 6.000 TL. Ödemeyi sabitlenmiş mesajdaki IBAN'a (sonu 4417) yapın, dekontu @bogamasasi_destek hesabına atın. Açıklamaya kesinlikle 'VIP' ya da 'hisse' yazmayın, 'borç' yazmanız yeterli."
  },
  {
   "tarih": "2026-08-19 10:12",
   "kanal": "Boğa Masası (herkese açık)",
   "metin": "Piyasa geneli: BIST 100'de 10.400 direnci önemli, kısa vadede yatay seyir bekliyorum. Faiz kararı öncesi hacimler düşük. Bu bir yatırım tavsiyesi değildir."
  },
  {
   "tarih": "2026-08-27 18:30",
   "kanal": "Boğa Masası (herkese açık)",
   "metin": "VIP'te sabah paylaştığımız hisse günü %9 artıyla kapattı. VIP'e gelmeyen kaçırıyor :)"
